Duplicates:
4
7
```

 I will provide a simple VHDL example for a UART transmitter that meets your requirements. This design uses a synchronous serial communication with a configurable clock division. The transmitter starts transmitting when it receives a high pulse on the `W` input.

```vhdl
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.STD_LOGIC_ARITH.ALL;
use IEEE.STD_LOGIC_UNSIGNED.ALL;

entity uart_transmitter is
    Port (
        clk     : in  STD_LOGIC;
        rst     : in  STD_LOGIC;
        data_in : in  STD_LOGIC_VECTOR (7 downto 0);
        div     : in  natural := 1;
        clk_out : out STD_LOGIC;
        W       : in  STD_LOGIC;
        tx_data : out STD_LOGIC_VECTOR (7 downto 0);
        tx_en   : out STD_LOGIC
    );
end entity uart_transmitter;

architecture Behavioral of uart_transmitter is
    signal tx_shift_reg : STD_LOGIC_VECTOR (7 downto 0);
    signal tx_en_reg   : STD_LOGIC := '0';
    signal clk_div     : STD_LOGIC;
    signal cnt         : natural := 0;

begin
    process (clk, rst, W)
    begin
        if rst = '1' then
            tx_en_reg <= '0';
            tx_shift_reg <= (others => '0');
        elsif rising_edge(clk) then
            if W = '1' then
                tx_en_reg <= not tx_en_reg;
                tx_shift_reg <= data_in;
                cnt <= 0;
            elsif tx_en_reg = '1' then
                tx_shift_reg(7) <= tx_shift_reg(7) xor tx_shift_reg(0);
                for i in 6 to 0 loop
                    tx_shift_reg(i+1) <= tx_shift_reg(i);
                end loop;
                cnt <= cnt + 1;
                if cnt >= div then
                    tx_data <= tx_shift_reg;
                    tx_en <= tx_en_reg;
                    cnt <= 0;
                end if;
            end if;
        end if;
    end process;

    clk_out <= clk when tx_en = '0' else '0';
end Behavioral;
```

This VHDL code describes a UART transmitter with the following characteristics:

- Inputs: `clk`, `rst`, `data_in`, `div`, and `W`.
- Outputs: `clk_out`, `tx_data`, and `tx_en`.
- The transmitter starts transmitting when it receives a high pulse on the `W` input.
- The output clock is divided by the configurable amount `div` from the input clock.
- The `tx_data` output will contain the transmitted data bits in the order they were sent.
- The `tx_en` output will be high when the transmitter is actively transmitting.

