  Serial.println(distance1);
  Serial.print("Distance 2: ");
  Serial.println(distance2);
  Serial.print("Distance 3: ");
  Serial.println(distance3);
  Serial.print("Distance 4: ");
  Serial.println(distance4);
  Serial.print("Distance 5: ");
